//! The shared example files of all SDKs (`sdk/cases/`), generated by the reference SDK.
//!
//! Each case is a program of SDK calls (`defs.rs`, `programs.rs`) and one or more runs, each
//! with an output configuration and a BUGGIFY configuration. For every run this test starts
//! itself as a child process (fresh SDK state: outcomes seen, sink, BUGGIFY configuration),
//! the child makes the calls through hydo-assert, and the parent collects what the sink
//! received and what the calls returned. That is the expected output that the Go, Python and
//! JavaScript SDKs' case tests compare their own bytes with.
//!
//!     cargo test --test cases                 # check: sdk/cases must equal what Rust writes
//!     HYDO_BLESS=1 cargo test --test cases    # (re)write sdk/cases after a format change
//!
//! File layout and the reader's rules: sdk/README.md, "The shared cases".

#[macro_use]
mod model;
mod defs;
mod programs;

use model::{Case, Run, Step};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

fn all_cases() -> Vec<Case> {
    let mut v = defs::all();
    v.extend(programs::all());
    let mut seen = std::collections::BTreeSet::new();
    for c in &v {
        assert!(seen.insert(c.id()), "two cases named {}", c.id());
        assert!(!c.runs.is_empty(), "{} has no run", c.id());
        if c.runs.len() > 1 {
            assert!(c.runs.iter().all(|r| !r.name.is_empty()), "{}: several runs need names", c.id());
        }
        let _ = c.prog.needs(); // validates key orders of invalid-UTF-8 keys
    }
    v
}

fn cases_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("cases")
}

// ---------------------------------------------------------------------------------------------
// The child: run one case's program with hydo-assert.

#[test]
fn case_child() {
    let Ok(id) = std::env::var("HYDO_CASE") else { return };
    let ret_path = std::env::var("HYDO_CASE_RETURNS").unwrap();
    let case = all_cases().into_iter().find(|c| c.id() == id).unwrap_or_else(|| panic!("no case {}", id));
    let returns = execute(&case.prog);
    std::fs::write(ret_path, returns).unwrap();
}

enum Obj {
    A(&'static hydo_assert::Assertion),
    L(&'static hydo_assert::Liveness),
    P(&'static hydo_assert::Point),
    S(&'static hydo_assert::Steer),
}

fn details(d: &Option<model::V>) -> hydo_assert::Details {
    match d {
        None => hydo_assert::Details::new(),
        Some(model::V::Map(m)) => m.iter().map(|(k, v)| (k.rust(), v.rust())).collect(),
        Some(other) => panic!("details must be a map: {:?}", other),
    }
}

fn execute(p: &model::Prog) -> String {
    use hydo_assert as ha;
    let mut objs: Vec<Obj> = Vec::new();
    let mut watches: Vec<hydo_assert::Watch> = Vec::new();
    let mut hists: Vec<ha::history::History> = Vec::new();
    let mut ops: Vec<Option<ha::history::Op>> = Vec::new();
    let mut ret = String::new();
    let mut push = |b: bool| ret.push(if b { '1' } else { '0' });
    let a = |objs: &Vec<Obj>, i: usize| match objs[i] {
        Obj::A(a) => a,
        _ => panic!("handle {} is not an assertion", i),
    };
    let args = |v: &[model::Arg]| v.iter().map(model::Arg::rust).collect::<Vec<String>>();
    for s in &p.steps {
        match s {
            Step::Decl { kind, id, msg } => {
                let (id, msg) = (id.rust(), msg.rust());
                objs.push(Obj::A(match *kind {
                    "always" => ha::always(id, msg),
                    "always_or_unreachable" => ha::always_or_unreachable(id, msg),
                    "sometimes" => ha::sometimes(id, msg),
                    "reachable" => ha::reachable(id, msg),
                    "unreachable" => ha::unreachable(id, msg),
                    k => panic!("kind {}", k),
                }));
            }
            Step::Eventually { id, msg, within_ms } => objs.push(Obj::L(ha::eventually(id.rust(), msg.rust(), Duration::from_millis(*within_ms)))),
            Step::Buggify { id, msg } => objs.push(Obj::P(ha::buggify(id.rust(), msg.rust()))),
            Step::Steer { goal, id, msg } => objs.push(Obj::S(if *goal == "min" { ha::minimize(id.rust(), msg.rust()) } else { ha::maximize(id.rust(), msg.rust()) })),
            Step::Value { a: i, v } => match objs[*i] {
                Obj::S(s) => s.value(*v),
                _ => panic!("value on {}", i),
            },
            Step::Check { a: i, cond, d } => push(a(&objs, *i).check(*cond, details(d))),
            Step::Hit { a: i, d } => a(&objs, *i).hit(details(d)),
            Step::Cmp { a: i, left, op, right, d, .. } => push(a(&objs, *i).cmp(*left, op, *right, details(d))),
            Step::Begin { a: i } => match objs[*i] {
                Obj::L(l) => watches.push(l.begin()),
                _ => panic!("begin on {}", i),
            },
            Step::Done { w, d } => push(watches[*w].done(details(d))),
            Step::Expire { w, d } => watches[*w].expire(details(d)),
            Step::Await { a: i, d, asyn } => {
                let Obj::L(l) = objs[*i] else { panic!("await on {}", i) };
                let ok = if *asyn {
                    let rt = tokio::runtime::Builder::new_current_thread().enable_time().build().unwrap();
                    rt.block_on(l.await_async(|| async { true }, Duration::from_millis(1), tokio::time::sleep, details(d)))
                } else {
                    l.await_cond(|| true, Duration::from_millis(1), details(d))
                };
                push(ok);
            }
            Step::Fire { a: i, d } => match objs[*i] {
                Obj::P(p) => push(p.fire(details(d))),
                _ => panic!("fire on {}", i),
            },
            Step::Catalog => ha::catalog(),
            Step::SetupComplete => ha::setup_complete(),
            Step::History { name } => hists.push(ha::history::History::new(name)),
            Step::Invoke { h, proc_, f, args: a2 } => {
                let v = args(a2);
                ops.push(Some(hists[*h].invoke(proc_, f, &v.iter().map(String::as_str).collect::<Vec<_>>())));
            }
            Step::Ok { o, args: a2 } => {
                let v = args(a2);
                ops[*o]
                    .take()
                    .expect("op completed twice")
                    .ok(&v.iter().map(String::as_str).collect::<Vec<_>>());
            }
            Step::OkSame { o } => ops[*o].take().expect("op completed twice").ok_same(),
            Step::Fail { o } => ops[*o].take().expect("op completed twice").fail(),
            Step::Info { o } => ops[*o].take().expect("op completed twice").info(),
            Step::Record { h, proc_, typ, f, args: a2 } => {
                let v = args(a2);
                hists[*h].record_raw(proc_, typ, f, &v.iter().map(String::as_str).collect::<Vec<_>>());
            }
        }
    }
    ret
}

// ---------------------------------------------------------------------------------------------
// The parent: run every case's runs, compare with (or write) sdk/cases.

const PRE: &str = "PRE existing line\n";

/// The Rust runner's stand-in for an invalid byte (model.rs) becomes what Go 1.26 writes: the
/// escape `�` inside JSON, the raw byte in a HYDO-HIST record.
fn unmark(out: &str) -> Vec<u8> {
    let mut v = Vec::new();
    for line in out.split_inclusive('\n') {
        let hist = line.starts_with("HYDO-HIST ");
        for c in line.chars() {
            let u = c as u32;
            if (0x10FF80..=0x10FFFF).contains(&u) {
                if hist {
                    v.push((u - 0x10FF00) as u8);
                } else {
                    v.extend_from_slice(b"\\ufffd");
                }
            } else {
                let mut b = [0u8; 4];
                v.extend_from_slice(c.encode_utf8(&mut b).as_bytes());
            }
        }
    }
    v
}

/// The time field of a HYDO-HIST record (field 5) becomes `*`; the times must be decimal
/// integers that never decrease, or `-` (the Rust recorder reads /proc/uptime, which a Mac
/// does not have).
fn mask_times(out: &[u8]) -> Result<Vec<u8>, String> {
    let mut v = Vec::new();
    let mut prev: Option<u128> = None;
    for line in out.split_inclusive(|b| *b == b'\n') {
        if line.starts_with(b"HYDO-HIST ") {
            let mut f: Vec<&[u8]> = line.splitn(6, |b| *b == b' ').collect();
            if f.len() < 6 {
                return Err(format!("short record {:?}", String::from_utf8_lossy(line)));
            }
            let t = std::str::from_utf8(f[4]).unwrap_or("?");
            if t != "-" {
                let n: u128 = t.parse().map_err(|_| format!("time {:?} is not a decimal integer", t))?;
                if prev.is_some_and(|p| n < p) {
                    return Err(format!("time {} is before the previous record's", n));
                }
                prev = Some(n);
            }
            f[4] = b"*";
            v.extend_from_slice(&f.join(&b' '));
        } else {
            v.extend_from_slice(line);
        }
    }
    Ok(v)
}

static SEQ: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

/// Runs one run of a case in a child process; returns the sink's bytes and the returns.
fn run_child(case: &Case, run: &Run) -> Result<(Vec<u8>, String), String> {
    let dir = std::env::temp_dir().join(format!(
        "hydo-cases-{}-{}",
        std::process::id(),
        SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let mut cmd = Command::new(std::env::current_exe().unwrap());
    cmd.args(["case_child", "--exact", "--nocapture", "--test-threads=1", "-q"]);
    cmd.env("HYDO_CASE", case.id())
        .env("HYDO_CASE_RETURNS", dir.join("returns"))
        .env_remove("HYDO_BLESS");
    match &run.buggify_env {
        Some(s) => cmd.env("HYDO_BUGGIFY", s),
        None => cmd.env_remove("HYDO_BUGGIFY"),
    };
    match &run.buggify_file {
        Some(s) => {
            std::fs::write(dir.join("buggify"), s).unwrap();
            cmd.env("HYDO_BUGGIFY_FILE", dir.join("buggify"))
        }
        None => cmd.env("HYDO_BUGGIFY_FILE", dir.join("no-buggify")),
    };
    let console = dir.join("console");
    match run.out {
        "file" | "append" => {
            std::fs::write(&console, if run.out == "append" { PRE } else { "" }).unwrap();
            cmd.env("HYDO_ASSERT_OUT", &console)
        }
        "stderr" => cmd.env("HYDO_ASSERT_OUT", "stderr"),
        "missing" => cmd.env("HYDO_ASSERT_OUT", dir.join("missing")),
        "off" => cmd.env("HYDO_ASSERT_OUT", "off"),
        o => panic!("out {}", o),
    };
    let hist = dir.join("hist");
    match run.hist_out {
        "file" | "append" => {
            std::fs::write(&hist, if run.hist_out == "append" { PRE } else { "" }).unwrap();
            cmd.env("HYDO_HIST_OUT", &hist)
        }
        "create" => cmd.env("HYDO_HIST_OUT", &hist),
        "stderr" => cmd.env("HYDO_HIST_OUT", "stderr"),
        "fallback" => cmd.env("HYDO_HIST_OUT", dir.join("no-such-dir").join("hist")),
        "off" => cmd.env("HYDO_HIST_OUT", "off"),
        o => panic!("hist_out {}", o),
    };
    assert!(run.out == "off" || run.hist_out == "off", "{}: a run has one sink", case.id());
    let o = cmd.output().unwrap();
    if !o.status.success() {
        return Err(format!(
            "child failed: {}\n{}{}",
            o.status,
            String::from_utf8_lossy(&o.stdout),
            String::from_utf8_lossy(&o.stderr)
        ));
    }
    let stderr_sink = matches!(run.out, "stderr" | "missing") || matches!(run.hist_out, "stderr" | "fallback");
    if !stderr_sink && !o.stderr.is_empty() {
        return Err(format!("wrote to stderr: {:?}", String::from_utf8_lossy(&o.stderr)));
    }
    let raw = if stderr_sink {
        o.stderr.clone()
    } else if run.out != "off" {
        std::fs::read(&console).unwrap()
    } else if run.hist_out != "off" {
        std::fs::read(&hist).map_err(|e| format!("history file: {}", e))?
    } else {
        Vec::new()
    };
    if run.out == "off" && run.hist_out == "off" && console.exists() {
        return Err("off wrote a file".into());
    }
    let text = String::from_utf8(raw).map_err(|_| "the Rust SDK wrote invalid UTF-8".to_string())?;
    let out = mask_times(&unmark(&text))?;
    let returns = std::fs::read_to_string(dir.join("returns")).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    Ok((out, returns))
}

fn first_difference(want: &[u8], got: &[u8]) -> String {
    let w: Vec<&[u8]> = want.split(|b| *b == b'\n').collect();
    let g: Vec<&[u8]> = got.split(|b| *b == b'\n').collect();
    for i in 0..w.len().max(g.len()) {
        let (a, b) = (w.get(i), g.get(i));
        if a != b {
            let show = |x: Option<&&[u8]>| x.map_or("(none)".to_string(), |l| String::from_utf8_lossy(l).into_owned());
            return format!("line {}:\n    file: {}\n    rust: {}", i + 1, show(a), show(b));
        }
    }
    "(equal)".into()
}

#[test]
fn cases() {
    if std::env::var_os("HYDO_CASE").is_some() || cfg!(feature = "noop") {
        return; // a child, or the feature that compiles every record away
    }
    let bless = std::env::var_os("HYDO_BLESS").is_some_and(|v| !v.is_empty());
    let root = cases_dir();
    let cases = all_cases();
    // what Rust writes, by path below sdk/cases
    let mut files: BTreeMap<PathBuf, Vec<u8>> = BTreeMap::new();
    let mut errors = Vec::new();
    for c in &cases {
        let mut returns = Vec::new();
        for r in &c.runs {
            match run_child(c, r) {
                Ok((out, ret)) => {
                    files.insert(Path::new(c.area).join(c.out_file(r)), out);
                    returns.push(ret);
                }
                Err(e) => {
                    errors.push(format!("{} run {:?}: {}", c.id(), r.name, e));
                    returns.push(String::new());
                }
            }
        }
        files.insert(Path::new(c.area).join(format!("{}.json", c.name)), c.json(&returns).into_bytes());
    }
    assert!(errors.is_empty(), "{}", errors.join("\n"));

    let mut present = Vec::new();
    if root.exists() {
        for area in std::fs::read_dir(&root).unwrap() {
            let area = area.unwrap().path();
            if area.is_dir() {
                for f in std::fs::read_dir(&area).unwrap() {
                    let f = f.unwrap().path();
                    let rel = f.strip_prefix(&root).unwrap().to_path_buf();
                    present.push(rel);
                }
            }
        }
    }
    if bless {
        for rel in &present {
            if !files.contains_key(rel) {
                std::fs::remove_file(root.join(rel)).unwrap();
                eprintln!("removed sdk/cases/{}", rel.display());
            }
        }
        let mut changed = 0;
        for (rel, bytes) in &files {
            let p = root.join(rel);
            if std::fs::read(&p).ok().as_deref() != Some(bytes.as_slice()) {
                std::fs::create_dir_all(p.parent().unwrap()).unwrap();
                std::fs::write(&p, bytes).unwrap();
                changed += 1;
                eprintln!("wrote sdk/cases/{}", rel.display());
            }
        }
        eprintln!("sdk/cases: {} cases, {} files, {} changed", cases.len(), files.len(), changed);
        return;
    }
    for rel in &present {
        if !files.contains_key(rel) {
            errors.push(format!("sdk/cases/{}: no case writes this file", rel.display()));
        }
    }
    for (rel, bytes) in &files {
        match std::fs::read(root.join(rel)) {
            Err(_) => errors.push(format!("sdk/cases/{}: missing", rel.display())),
            Ok(have) if have != *bytes => errors.push(format!(
                "sdk/cases/{} differs from what Rust writes, {}",
                rel.display(),
                first_difference(&have, bytes)
            )),
            Ok(_) => {}
        }
    }
    assert!(
        errors.is_empty(),
        "{}\n\nIf the change is intended, regenerate the cases: HYDO_BLESS=1 cargo test --test cases",
        errors.join("\n")
    );
}
